INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, main_image_key, main_image_caption, image_credit, is_featured, is_breaking, status, published_at) VALUES
('demo-pune-01','शिवनेरी किल्ल्यावर पर्यटकांसाठी नवीन सुविधा; पायवाटेची दुरुस्ती पूर्ण',
 'पिण्याचे पाणी, माहितीफलक आणि विश्रांती कट्ट्यांमुळे गडभेट अधिक सोयीची होणार',
 '<p>जुन्नर येथील शिवनेरी किल्ल्यावर येणाऱ्या पर्यटकांसाठी पायवाटेची दुरुस्ती आणि नवीन सुविधांचे काम पूर्ण झाल्याची माहिती स्थानिक प्रशासनाने दिली. पावसाळ्यात खचलेल्या पायऱ्यांची डागडुजी करण्यात आली असून घसरडे भाग सुरक्षित करण्यात आले आहेत.</p><p>गडावर पिण्याच्या पाण्याची व्यवस्था, ऐतिहासिक माहिती देणारे फलक आणि ज्येष्ठ नागरिकांसाठी विश्रांती कट्टे उभारण्यात आले आहेत. सुट्ट्यांच्या दिवसांत होणारी गर्दी लक्षात घेऊन स्वयंसेवकांची मदतही घेतली जाणार आहे.</p><h2>स्वच्छतेचे आवाहन</h2><p>गडावर प्लास्टिक नेऊ नये आणि कचरा परत खाली आणावा, असे आवाहन स्थानिक दुर्गप्रेमी संस्थांनी केले आहे.</p><p><em>(ही डेमो बातमी आहे – वेबसाइट चाचणीसाठी तयार केलेली.)</em></p>',
 (SELECT id FROM categories WHERE slug='social'),'जुन्नर','जुन्नर प्रतिनिधी','डेमो माहिती (चाचणी)','img/2026/11/demo01.jpg','शिवनेरी किल्ला परिसर (प्रतीकात्मक चित्र)','NEWS24 SHIVNERI (डेमो)',1,0,'published',strftime('%Y-%m-%dT%H:%M:%SZ','now','-40 minutes')),
('demo-pune-02','नारायणगाव बाजारात टोमॅटोची आवक वाढली; दर स्थिर',
 'चांगल्या पावसामुळे उत्पादन वाढल्याचे शेतकऱ्यांचे मत',
 '<p>नारायणगाव येथील उपबाजारात या आठवड्यात टोमॅटोची आवक लक्षणीय वाढली. जुन्नर, आंबेगाव आणि खेड तालुक्यांतून शेतकरी मोठ्या प्रमाणात माल घेऊन आले होते.</p><p>आवक वाढूनही दर स्थिर राहिल्याने शेतकऱ्यांना दिलासा मिळाला. व्यापाऱ्यांच्या म्हणण्यानुसार मुंबई आणि गुजरातमधून मागणी कायम आहे.</p><p>शेतमाल वेळेवर बाजारात पोहोचवण्यासाठी वाहतूक व्यवस्था सुधारावी, अशी मागणी शेतकऱ्यांनी केली.</p><p><em>(ही डेमो बातमी आहे – वेबसाइट चाचणीसाठी तयार केलेली.)</em></p>',
 (SELECT id FROM categories WHERE slug='agriculture'),'नारायणगाव','कृषी प्रतिनिधी','डेमो माहिती (चाचणी)','img/2026/11/demo02.jpg','जुन्नर तालुक्यातील शेती (प्रतीकात्मक चित्र)',NULL,0,0,'published',strftime('%Y-%m-%dT%H:%M:%SZ','now','-2 hours')),
('demo-pune-03','पुणे-नाशिक महामार्गावर चाकणजवळ वाहतूक कोंडी; पर्यायी मार्ग सुचवले',
 'सकाळी आणि संध्याकाळी गर्दीच्या वेळेत प्रवाशांनी नियोजन करावे',
 '<p>पुणे-नाशिक महामार्गावर चाकण परिसरात रस्ता रुंदीकरणाच्या कामामुळे वाहतूक संथ गतीने सुरू आहे. वाहतूक पोलिसांनी काही पर्यायी मार्ग सुचवले आहेत.</p><p>औद्योगिक वसाहतीतील कामगारांच्या वेळा लक्षात घेऊन जड वाहनांच्या वेळेत बदल करण्याचा विचार सुरू असल्याचे सांगण्यात आले.</p><p><em>(ही डेमो बातमी आहे – वेबसाइट चाचणीसाठी तयार केलेली.)</em></p>',
 (SELECT id FROM categories WHERE slug='pune-district'),'चाकण, खेड','खेड प्रतिनिधी','डेमो माहिती (चाचणी)','img/2026/11/demo13.jpg','महामार्ग (प्रतीकात्मक चित्र)',NULL,0,1,'published',strftime('%Y-%m-%dT%H:%M:%SZ','now','-25 minutes')),
('demo-pune-04','मंचर येथील जिल्हा परिषद शाळेत विज्ञान प्रदर्शन; ६० प्रकल्प सादर',
 'सौरऊर्जा, पाणी बचत आणि कचरा व्यवस्थापनावरील प्रकल्पांना विशेष दाद',
 '<p>आंबेगाव तालुक्यातील मंचर येथे जिल्हा परिषद शाळेत आयोजित विज्ञान प्रदर्शनात परिसरातील शाळांच्या विद्यार्थ्यांनी ६० प्रकल्प सादर केले.</p><p>सौरऊर्जेवर चालणारा पंप, ठिबक सिंचनाचे मॉडेल आणि ओल्या कचऱ्यापासून खतनिर्मिती या प्रकल्पांनी पालक व शिक्षकांचे लक्ष वेधले.</p><ul><li>प्रथम क्रमांक: पाणी बचत प्रकल्प</li><li>द्वितीय क्रमांक: सौर पंप</li><li>तृतीय क्रमांक: कचरा व्यवस्थापन</li></ul><p><em>(ही डेमो बातमी आहे – वेबसाइट चाचणीसाठी तयार केलेली.)</em></p>',
 (SELECT id FROM categories WHERE slug='education'),'मंचर, आंबेगाव','शिक्षण प्रतिनिधी','डेमो माहिती (चाचणी)','img/2026/11/demo04.jpg','जिल्हा परिषद शाळा (प्रतीकात्मक चित्र)',NULL,0,0,'published',strftime('%Y-%m-%dT%H:%M:%SZ','now','-3 hours')),
('demo-pune-05','खडकवासला धरणसाखळीत समाधानकारक पाणीसाठा',
 'पुढील उन्हाळ्यापर्यंत पिण्याच्या पाण्याची चिंता नसल्याचा अंदाज',
 '<p>पुणे शहराला पाणीपुरवठा करणाऱ्या खडकवासला धरणसाखळीत यंदा समाधानकारक पाणीसाठा असल्याची माहिती जलसंपदा विभागाच्या सूत्रांनी दिली.</p><p>शेतीसाठी रब्बी हंगामात आवर्तने देण्याचे नियोजन सुरू आहे. नागरिकांनी पाण्याचा काटकसरीने वापर करावा, असे आवाहनही करण्यात आले.</p><p><em>(ही डेमो बातमी आहे – वेबसाइट चाचणीसाठी तयार केलेली.)</em></p>',
 (SELECT id FROM categories WHERE slug='pune-district'),'खडकवासला, हवेली','पुणे प्रतिनिधी','डेमो माहिती (चाचणी)','img/2026/11/demo08.jpg','धरण (प्रतीकात्मक चित्र)',NULL,0,0,'published',strftime('%Y-%m-%dT%H:%M:%SZ','now','-4 hours')),
('demo-pune-06','बारामतीत आंतरशालेय क्रिकेट स्पर्धेला सुरुवात; १६ संघ सहभागी',
 NULL,
 '<p>बारामती येथे आंतरशालेय क्रिकेट स्पर्धेला उत्साहात सुरुवात झाली. तालुक्यातील १६ शाळांचे संघ या स्पर्धेत सहभागी झाले आहेत.</p><p>स्पर्धेचा अंतिम सामना रविवारी होणार असून विजेत्या संघाला चषक आणि खेळाडूंना प्रमाणपत्रे दिली जाणार आहेत.</p><p><em>(ही डेमो बातमी आहे – वेबसाइट चाचणीसाठी तयार केलेली.)</em></p>',
 (SELECT id FROM categories WHERE slug='sports'),'बारामती','क्रीडा प्रतिनिधी','डेमो माहिती (चाचणी)','img/2026/11/demo06.jpg','क्रिकेट मैदान (प्रतीकात्मक चित्र)',NULL,0,0,'published',strftime('%Y-%m-%dT%H:%M:%SZ','now','-5 hours')),
('demo-pune-07','शिरूर येथे ग्रामसभेत रस्ते व पाणीपुरवठ्याच्या कामांना मंजुरी',
 'पुढील तीन महिन्यांत कामे सुरू करण्याचा ठराव',
 '<p>शिरूर तालुक्यातील एका ग्रामपंचायतीच्या ग्रामसभेत अंतर्गत रस्ते आणि पाणीपुरवठा योजनेच्या कामांना मंजुरी देण्यात आली.</p><p>ग्रामस्थांनी गटारांची स्वच्छता आणि पथदिव्यांच्या दुरुस्तीचे मुद्दे मांडले. कामांचा दर्जा तपासण्यासाठी ग्रामस्थांची समिती नेमण्याचा निर्णयही घेण्यात आला.</p><p><em>(ही डेमो बातमी आहे – वेबसाइट चाचणीसाठी तयार केलेली.)</em></p>',
 (SELECT id FROM categories WHERE slug='politics'),'शिरूर','शिरूर प्रतिनिधी','डेमो माहिती (चाचणी)','img/2026/11/demo14.jpg','ग्रामसभा (प्रतीकात्मक चित्र)',NULL,0,0,'published',strftime('%Y-%m-%dT%H:%M:%SZ','now','-6 hours')),
('demo-pune-08','लोणावळ्यात पावसाळी पर्यटन हंगाम संपला; व्यावसायिक समाधानी',
 NULL,
 '<p>मावळ तालुक्यातील लोणावळा परिसरात यंदाच्या पावसाळी पर्यटन हंगामात चांगली गर्दी झाल्याने स्थानिक व्यावसायिक समाधानी आहेत.</p><p>धबधब्यांच्या ठिकाणी सुरक्षा उपाययोजनांमुळे दुर्घटनांचे प्रमाण कमी राहिल्याचे स्थानिकांनी सांगितले.</p><p><em>(ही डेमो बातमी आहे – वेबसाइट चाचणीसाठी तयार केलेली.)</em></p>',
 (SELECT id FROM categories WHERE slug='business'),'लोणावळा, मावळ','मावळ प्रतिनिधी','डेमो माहिती (चाचणी)','img/2026/11/demo09.jpg','सह्याद्रीतील पाऊस (प्रतीकात्मक चित्र)',NULL,0,0,'published',strftime('%Y-%m-%dT%H:%M:%SZ','now','-7 hours')),
('demo-pune-09','आळेफाटा येथे यात्रेनिमित्त लोककला महोत्सव',
 'तमाशा, भारूड आणि पोवाड्यांच्या कार्यक्रमांना मोठी गर्दी',
 '<p>जुन्नर तालुक्यातील आळेफाटा परिसरात ग्रामदैवताच्या यात्रेनिमित्त लोककला महोत्सव आयोजित करण्यात आला. पारंपरिक कलांना प्रोत्साहन देणे हा या महोत्सवाचा उद्देश असल्याचे आयोजकांनी सांगितले.</p><p>स्थानिक कलाकारांनी सादर केलेल्या पोवाड्यांना प्रेक्षकांनी उत्स्फूर्त दाद दिली.</p><p><em>(ही डेमो बातमी आहे – वेबसाइट चाचणीसाठी तयार केलेली.)</em></p>',
 (SELECT id FROM categories WHERE slug='entertainment'),'आळेफाटा, जुन्नर','प्रतिनिधी','डेमो माहिती (चाचणी)','img/2026/11/demo07.jpg','उत्सव (प्रतीकात्मक चित्र)',NULL,0,0,'published',strftime('%Y-%m-%dT%H:%M:%SZ','now','-8 hours')),
('demo-pune-10','इंदापूर तालुक्यात ऊस तोडणी हंगाम सुरू',
 'कारखान्यांकडून वाहतूक आणि तोडणी मजुरांसाठी सोयींची तयारी',
 '<p>इंदापूर तालुक्यात यंदाचा ऊस गळीत हंगाम सुरू झाला आहे. परिसरातील साखर कारखान्यांनी तोडणी मजुरांसाठी निवारा, पाणी आणि आरोग्य तपासणीची व्यवस्था केली आहे.</p><p>ऊस वेळेत तोडला जावा यासाठी तोडणी कार्यक्रम आधीच जाहीर करावा, अशी मागणी शेतकऱ्यांनी केली.</p><p><em>(ही डेमो बातमी आहे – वेबसाइट चाचणीसाठी तयार केलेली.)</em></p>',
 (SELECT id FROM categories WHERE slug='agriculture'),'इंदापूर','इंदापूर प्रतिनिधी','डेमो माहिती (चाचणी)','img/2026/11/demo10.jpg','शेतातील संध्याकाळ (प्रतीकात्मक चित्र)',NULL,0,0,'published',strftime('%Y-%m-%dT%H:%M:%SZ','now','-10 hours')),
('demo-pune-11','पिंपरी-चिंचवडमध्ये रात्रीच्या बससेवेचा विस्तार',
 NULL,
 '<p>पिंपरी-चिंचवड परिसरात रात्री उशिरा काम संपवून घरी जाणाऱ्या कामगारांसाठी बससेवेचा विस्तार करण्यात आल्याचे परिवहन सूत्रांनी सांगितले.</p><p>औद्योगिक भागांतून प्रमुख चौकांपर्यंत नवीन फेऱ्या सुरू करण्यात आल्या आहेत. प्रवाशांच्या प्रतिसादानुसार आणखी मार्ग वाढवले जातील.</p><p><em>(ही डेमो बातमी आहे – वेबसाइट चाचणीसाठी तयार केलेली.)</em></p>',
